insert into page_content (page_key, section_key, draft_content, published_content, requires_verification, published_at)
values
  ('site', 'profile',
   '{"name":"Ekrem Eray Arda","title":"İBB ve Kartal Belediye Meclis Üyesi","description":"Ekrem Eray Arda''nın çalışmaları, açıklamaları ve medya içerikleri için kişisel kamusal web sitesi."}'::jsonb,
   '{"name":"Ekrem Eray Arda","title":"İBB ve Kartal Belediye Meclis Üyesi","description":"Ekrem Eray Arda''nın çalışmaları, açıklamaları ve medya içerikleri için kişisel kamusal web sitesi."}'::jsonb,
   false, now()),
  ('about', 'biography',
   $json${
     "heroSummary":"1985 yılında İstanbul'da doğan Ekrem Eray Arda, ilk ve ortaöğrenimini Kartal'da tamamladı. İş dünyası, spor ve yerel yönetimlerde görev aldı. 2024 yılından bu yana Kartal ve İstanbul Büyükşehir Belediye Meclislerinde görev yapmaktadır.",
     "sections":[
       {"number":"01","category":"Hakkında","title":"Kartal'dan İstanbul'a uzanan bir yaşam.","paragraphs":["İstanbul'da doğan ve ilk eğitim yıllarını Kartal'da geçiren Ekrem Eray Arda, eğitimini siyaset bilimi ve uluslararası ilişkiler alanlarında sürdürdü. Spor, iş dünyası ve yerel yönetimlerde farklı görevler üstlendi."]},
       {"number":"02","category":"Eğitim","title":"Eğitim ve akademik yaşam","paragraphs":["25 Mart 1985'te İstanbul'da doğdu. Girne Amerikan Üniversitesi'nde İşletme eğitimi aldı. İstanbul Bilgi Üniversitesi Siyaset Bilimi Bölümü'nden mezun oldu ve Bahçeşehir Üniversitesi'nde Küresel Siyaset ve Uluslararası İlişkiler alanında yüksek lisans yaptı."]},
       {"number":"03","category":"Spor","title":"Disiplin, Azim ve Takım Ruhu","paragraphs":["1999–2004 yılları arasında Fenerbahçe Kürek Takımı'nda sporcu olarak yer aldı ve takım kaptanlığı yaptı."]},
       {"number":"04","category":"İş Hayatı","title":"Girişimcilik ve yönetim tecrübesi","paragraphs":["Genç yaşlardan itibaren iş dünyasında farklı alanlarda faaliyet gösteren Ekrem Eray Arda, girişimcilik ve yöneticilik alanlarında deneyim kazandı."]},
       {"number":"05","category":"Siyasi Yaşam","title":"Siyasi yaşam ve yerel yönetim","paragraphs":["2019 yılında Çekmeköy Belediye Meclis Üyesi seçildi. Demokrat Parti İstanbul İl Başkanlığı görevini yürüttü. 2024 yerel seçimlerinde Kartal Belediye Meclisi ve İstanbul Büyükşehir Belediye Meclisine seçildi. Eylül 2026'da CHP'den ayrılarak görevlerine bağımsız meclis üyesi olarak devam edeceğini açıkladı."],"subsections":[{"title":"Meclis ve komisyon görevleri","paragraphs":["Kartal Belediye Meclisi Gençlik ve Spor Komisyonu Başkanı ve AB ve Dış İlişkiler Komisyonu üyesidir. İstanbul Büyükşehir Belediye Meclisinde Gençlik ve Spor Komisyonu üyeliği görevini de yürütmektedir."]}],"requiresOfficialVerification":true}
     ]
   }$json$::jsonb,
   $json${
     "heroSummary":"1985 yılında İstanbul'da doğan Ekrem Eray Arda, ilk ve ortaöğrenimini Kartal'da tamamladı. İş dünyası, spor ve yerel yönetimlerde görev aldı. 2024 yılından bu yana Kartal ve İstanbul Büyükşehir Belediye Meclislerinde görev yapmaktadır.",
     "sections":[
       {"number":"01","category":"Hakkında","title":"Kartal'dan İstanbul'a uzanan bir yaşam.","paragraphs":["İstanbul'da doğan ve ilk eğitim yıllarını Kartal'da geçiren Ekrem Eray Arda, eğitimini siyaset bilimi ve uluslararası ilişkiler alanlarında sürdürdü. Spor, iş dünyası ve yerel yönetimlerde farklı görevler üstlendi."]},
       {"number":"02","category":"Eğitim","title":"Eğitim ve akademik yaşam","paragraphs":["25 Mart 1985'te İstanbul'da doğdu. Girne Amerikan Üniversitesi'nde İşletme eğitimi aldı. İstanbul Bilgi Üniversitesi Siyaset Bilimi Bölümü'nden mezun oldu ve Bahçeşehir Üniversitesi'nde Küresel Siyaset ve Uluslararası İlişkiler alanında yüksek lisans yaptı."]},
       {"number":"03","category":"Spor","title":"Disiplin, Azim ve Takım Ruhu","paragraphs":["1999–2004 yılları arasında Fenerbahçe Kürek Takımı'nda sporcu olarak yer aldı ve takım kaptanlığı yaptı."]},
       {"number":"04","category":"İş Hayatı","title":"Girişimcilik ve yönetim tecrübesi","paragraphs":["Genç yaşlardan itibaren iş dünyasında farklı alanlarda faaliyet gösteren Ekrem Eray Arda, girişimcilik ve yöneticilik alanlarında deneyim kazandı."]},
       {"number":"05","category":"Siyasi Yaşam","title":"Siyasi yaşam ve yerel yönetim","paragraphs":["2019 yılında Çekmeköy Belediye Meclis Üyesi seçildi. Demokrat Parti İstanbul İl Başkanlığı görevini yürüttü. 2024 yerel seçimlerinde Kartal Belediye Meclisi ve İstanbul Büyükşehir Belediye Meclisine seçildi. Eylül 2026'da CHP'den ayrılarak görevlerine bağımsız meclis üyesi olarak devam edeceğini açıkladı."],"subsections":[{"title":"Meclis ve komisyon görevleri","paragraphs":["Kartal Belediye Meclisi Gençlik ve Spor Komisyonu Başkanı ve AB ve Dış İlişkiler Komisyonu üyesidir. İstanbul Büyükşehir Belediye Meclisinde Gençlik ve Spor Komisyonu üyeliği görevini de yürütmektedir."]}],"requiresOfficialVerification":true}
     ]
   }$json$::jsonb,
   true, now())
on conflict (page_key, section_key) do nothing;

